import Foundation

enum AppLanguage: String, CaseIterable, Identifiable {
    case en, ru, de, es, pt, fr, it, zh, ja, nl

    var id: String { rawValue }

    /// Languages written right to left. Hop picks its language in-app rather
    /// than through the system locale, so nothing else can tell SwiftUI which
    /// way a window should run – see `hopLayoutDirection()`.
    var isRTL: Bool { false }

    var nativeName: String {
        switch self {
        case .en: return "English"
        case .ru: return "Русский"
        case .de: return "Deutsch"
        case .es: return "Español"
        case .pt: return "Português"
        case .fr: return "Français"
        case .it: return "Italiano"
        case .zh: return "中文"
        case .ja: return "日本語"
        case .nl: return "Nederlands"
        }
    }

    /// English name – used only for alphabetical ordering in lists.
    var englishName: String {
        switch self {
        case .en: return "English"
        case .ru: return "Russian"
        case .de: return "German"
        case .es: return "Spanish"
        case .pt: return "Portuguese"
        case .fr: return "French"
        case .it: return "Italian"
        case .zh: return "Chinese"
        case .ja: return "Japanese"
        case .nl: return "Dutch"
        }
    }

    /// Order for language pickers – standard, matching system lists:
    /// alphabet of NATIVE names (Deutsch, English, Español… then Russian and 中文 by their native names).
    /// FINAL decision by Anton 2026-07-13 ("the way it's officially written everywhere");
    /// an English-alphabet variant was tried and reverted.
    static var pickerOrder: [AppLanguage] {
        allCases.sorted { $0.nativeName.localizedCompare($1.nativeName) == .orderedAscending }
    }

    /// The system language if we support it; English otherwise.
    static var system: AppLanguage {
        for preferred in Locale.preferredLanguages {
            let code = String(preferred.prefix(2))
            if let lang = AppLanguage(rawValue: code) { return lang }
        }
        return .en
    }
}

