enum L10n {
    /// "auto" in UserDefaults = follow the system language.
    static var current: AppLanguage {
        resolve(UserDefaults.standard.string(forKey: SettingsKey.appLanguage))
    }

    static func resolve(_ raw: String?) -> AppLanguage {
        guard let raw, let lang = AppLanguage(rawValue: raw) else { return .system }
        return lang
    }

    /// Translation completeness diagnostics (dev mode --l10n-check).
    static func missingKeys() -> [String] {
        var out: [String] = []
        for lang in AppLanguage.allCases {
            for key in L10nKey.allCases where tables[lang]?[key] == nil {
                out.append("\(lang.rawValue).\(key.rawValue)")
            }
        }
        return out
    }

    /// Substitutes a value into a translated sentence. The value carries its own
    /// direction – a Latin file name, a figure like "5.1 GB", a version number –
    /// so it is wrapped in Unicode isolates. Without them a right-to-left
    /// sentence pulls the neighbouring punctuation to the wrong end of the value
    /// and "5.1 GB given back." reads as ".5.1 GB given back".
    static func fill(_ key: L10nKey, _ lang: AppLanguage, _ value: String) -> String {
        let isolated = lang.isRTL ? "\u{2068}" + value + "\u{2069}" : value
        return t(key, lang).replacingOccurrences(of: "%@", with: isolated)
    }

    static func t(_ key: L10nKey, _ lang: AppLanguage) -> String {
        tables[lang]?[key] ?? tables[.en]?[key] ?? key.rawValue
    }

    private static let tables: [AppLanguage: [L10nKey: String]] = [
        .en: [
            .memPressureNote: "memory: macOS's own memory-pressure signal colors the row too, and the worse of the two wins",
            .thSwap: "swap % of ram",
            .windowsInDock: "show the hop icon in the dock",
            .windowsInDockNote: "the icon appears while a window is open and brings it back on a click. without it hop only leaves the dock: the menu bar icon, the hotkeys and everything running in the background stay as they were.",
            .thermalNote: "temperature: the color follows macOS's own thermal state, not a fixed number",
            .aboutTabNews: "what's new", .newsAllReleases: "all releases",
            .docNews: "1.10.0 – 2026-09-03\n\n• settings are a window – a sidebar instead of tabs inside the panel, a page per module saying in two sentences what it does, every hotkey in one place, and about, what's new and the handbook alongside them\n\n• the handbook is back in the app – the full instructions for every module, no longer only a page on the site\n\n• permissions on one page – what is granted, what is not, and a button that asks for it right there instead of sending you to a switch that is already on. updating to this version clears every permission once and asks again: a permission belongs to a signature, and hop's changed when apple signed it. from here on they survive an update\n\n• the keyboard lock proves itself – the cover goes up only once the keys have actually gone quiet, a check repeats every second for as long as the lock stands, the countdown bar tells the truth, and the dock no longer floats over a locked screen\n\n• nothing fails in silence – a feature stopped by a missing permission says so in one line, and that line is the button that asks for it\n\n• the icon's menu – a right click opens the handbook and about, not only settings\n\n1.9.1 – 2026-08-31\n\n• signed by apple – hop now carries an apple developer id and apple's notarisation, so macos opens it without the warning a first install used to show. the signature is new, which makes hop a new app to macos: the permissions you had granted are gone, and hop asks for each one again when it needs it\n\n• vpn, faster – a tunnel's state is taken from the system the moment it changes, so the dot in the menu bar follows a connection going up or down without a wait. it holds for clients that leave their interface standing after the session itself is gone\n\n• what a release brought – a card at the top of the panel names what a new version added, with the full notes one button away. it arrives with the update, keeps to a couple of showings and leaves on its own\n\n1.9.0 – 2026-08-29\n\n• projects and history in the tracker – tasks can be grouped into projects, each with its own sum, and one switch above the list shows today, this week or all of it. open a task and every stretch of time it collected is listed: change how long one ran or when it happened, add a session nobody pressed play for, or throw one away. a star now lifts a task to the top of its own list. the row counts the run you are in, from zero, and the ✓ beside it closes the run – the period's sum comes back and the next start begins at zero\n\n• one button for where the video goes – reels, feed, tiktok, shorts or youtube sets the frame, the resolution and how hard to squeeze, from what the platform itself recommends. the dial says the bitrate it means, in megabits, so what you are trading is visible\n\n• mkv and webm at last – macOS opens neither, so hop repacks them into mp4 first, copying the picture across untouched, and everything else works as usual. a small helper downloads once, the first time you convert one\n\n• pages, numbers and keynote – drop a pile of them in and they come out as pdf, or as docx, xlsx and pptx. the documents are exported by the apps themselves, so the result is what «export to…» gives, formulas included\n\n• smaller things – an image asked for in the format it already is, at full quality, is copied instead of re-encoded (it used to come back several times heavier); durations are always written in full, h:mm:ss; and the converter's settings line up in one column\n\n1.8.0 – 2026-08-04\n\n• video for where it is going – a clip can be reframed as it converts: 9:16 for reels and stories, 4:5 or square for a feed, 16:9 for everything else. a picture of another shape is cropped to fill, padded, or laid over a blurred copy of itself – your choice, and nothing is ever stretched\n\n• compression that compresses – the switch used to change almost nothing, because the system's own settings re-encode a video back to about the size it started at. hop now encodes it itself, with a level you set, and the size it promises is the size you get. the container stays what it was: an mp4 comes out an mp4\n\n• two clocks in the menu bar – a timer and a tracked task share the one spot now, five seconds each, with a small mark in front of the digits saying which is speaking. a clock stopped while the panel is open keeps its place instead of leaving a gap\n\n• pdf into markdown, faster – the same text and the same headings in a fraction of the time, up to eight times quicker on documents whose fonts macOS has to work at\n\n• after converting – the bar moves with the work rather than in jumps, a sound says the batch is done, and a button opens the folder the files went to with one already selected. anything macOS cannot open at all (mkv, webm) is named as such the moment you drop it, not after you press convert\n\n1.7.1 – 2026-07-31\n\n• vpn – the dot on the icon turns orange when a tunnel is on but nothing is coming back through it, so a connection that quietly died stops looking like a working one. the panel marks which tunnel it means, and the dot now stays right while the panel is closed\n\n• cleaning up – leftovers belonging to a program you still have installed are no longer offered: on a real Mac seven of the eight rows had an owner\n\n• the cleanup window reads shorter – the line repeated under every row is gone, since the heading above them already says what they are",
